import sys

import numpy as np
import wgpu

SHADER = """
struct Params { w: u32, h: u32 };
@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.w || id.y >= p.h) { return; }
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy++) {
        for (var dx: i32 = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) { continue; }
            let x = i32(id.x) + dx;
            let y = i32(id.y) + dy;
            if (x < 0 || y < 0 || x >= i32(p.w) || y >= i32(p.h)) { continue; }
            n += src[u32(y) * p.w + u32(x)];
        }
    }
    let i = id.y * p.w + id.x;
    let alive = src[i] == 1u;
    dst[i] = select(u32(n == 3u), u32(n == 2u || n == 3u), alive);
}
"""


def parse(path):
    with open(path) as f:
        tokens = f.read().split()
    w, h, gens = int(tokens[0]), int(tokens[1]), int(tokens[2])
    digits = "".join(tokens[3:])
    cells = np.array([c == "1" for c in digits[: w * h]], dtype=np.uint32)
    if cells.size < w * h:
        cells = np.concatenate([cells, np.zeros(w * h - cells.size, np.uint32)])
    return w, h, gens, cells


def run_gpu(w, h, gens, cells):
    if gens == 0:
        return cells
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    usage = wgpu.BufferUsage
    size = w * h * 4
    bufs = [
        device.create_buffer_with_data(
            data=cells.tobytes(),
            usage=usage.STORAGE | usage.COPY_SRC | usage.COPY_DST,
        ),
        device.create_buffer(
            size=size, usage=usage.STORAGE | usage.COPY_SRC | usage.COPY_DST
        ),
    ]
    params = device.create_buffer_with_data(
        data=np.array([w, h], dtype=np.uint32).tobytes(),
        usage=usage.UNIFORM,
    )
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)
    groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params}},
                {"binding": 1, "resource": {"buffer": bufs[i]}},
                {"binding": 2, "resource": {"buffer": bufs[1 - i]}},
            ],
        )
        for i in range(2)
    ]
    gx, gy = (w + 7) // 8, (h + 7) // 8
    # Submit in batches to keep command buffers modest.
    done = 0
    while done < gens:
        n = min(100, gens - done)
        enc = device.create_command_encoder()
        cp = enc.begin_compute_pass()
        cp.set_pipeline(pipeline)
        for g in range(done, done + n):
            cp.set_bind_group(0, groups[g % 2])
            cp.dispatch_workgroups(gx, gy, 1)
        cp.end()
        device.queue.submit([enc.finish()])
        done += n
    data = device.queue.read_buffer(bufs[gens % 2])
    return np.frombuffer(data, dtype=np.uint32, count=w * h).copy()


def main():
    w, h, gens, cells = parse(sys.argv[1])
    out = run_gpu(w, h, gens, cells)
    grid = out.reshape(h, w)
    lines = [" ".join("1" if v else "0" for v in row) for row in grid]
    lines.append("ALIVE %d" % int(grid.sum()))
    sys.stdout.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
